<template><div class="settings-grid"><el-card shadow="never"><template #header><b>基本信息</b></template><el-form label-position="top" v-loading="loading"><el-form-item label="项目名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="项目说明"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="项目类型"><el-select v-model="form.project_kind"><el-option label="完整测试项目" value="full"/><el-option label="接口测试项目" value="api_testing"/><el-option label="源码分析项目" value="source_analysis"/></el-select></el-form-item><el-button type="primary" @click="save">保存基本信息</el-button></el-form></el-card><ProjectContext/></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import{projectApi}from'@/api';import ProjectContext from'./ProjectContext.vue';const projectId=String(useRoute().params.id),loading=ref(false),form=reactive({name:'',description:'',project_kind:'full'});onMounted(async()=>{loading.value=true;try{const r:any=await projectApi.get(projectId);Object.assign(form,r?.data||{})}finally{loading.value=false}});async function save(){await projectApi.update(projectId,form);ElMessage.success('项目设置已保存')}</script>
<style scoped>.settings-grid{display:grid;gap:14px}.el-select{width:100%}</style>
